const item = $input.first().json;
return [{ json: {
  input_text:           item.input_text,
  start_time_ms:        item.start_time_ms,
  input_token_estimate: item.input_token_estimate,
  iteration:            1,
  max_revisions:        3,
  current_draft:        '',
  human_feedback:       '',
  review_history:       [],
  is_approved:          false
} }];

const state = $input.first().json;
let promptText;
if (state.iteration === 1) {
  promptText = `You are a helpful assistant. Complete the following task as accurately and thoroughly as possible.

Task: ${state.input_text}`;
} else {
  promptText = `You are a helpful assistant. A human reviewer has rejected your previous response and provided feedback. Revise your response to fully address all feedback.

Original task:
${state.input_text}

Your previous response:
${state.current_draft}

Reviewer feedback:
${state.human_feedback}

Provide an improved response that fully addresses the feedback.`;
}
return [{ json: { ...state, prompt_text: promptText } }];

const draft = ($input.first().json.text || '').trim();
const state = $('Format Agent Prompt').first().json;
const fullResumeUrl = $execution.resumeUrl;
const pathMatch = fullResumeUrl.match(/\/webhook-waiting\/.+/);
const resumeUrl = pathMatch ? 'http://localhost:5678' + pathMatch[0] : fullResumeUrl;
return [{ json: {
  ...state,
  current_draft: draft,
  status:        'pending_review',
  draft,
  resume_url:    resumeUrl,
  instructions:  'POST to resume_url with { "decision": "approve" } or { "decision": "reject", "feedback": "your feedback" }'
} }];

const item   = $input.first().json;
const prev   = $('Prepare Review Response').first().json;
const body   = item.body || item;
const decision = (body.decision || 'reject').toLowerCase().trim();
const feedback = (body.feedback || '').trim();
const isApproved  = decision === 'approve';

// Capture the draft that was reviewed so execution_trace can reference raw LLM output
const draftSnapshot          = prev.current_draft || '';
const draftOutputTokenEstimate = Math.ceil(draftSnapshot.length / 4);

// Per-revision input token estimate:
//   Revision 1 — only the original task prompt
//   Revision 2+ — original task + previous draft + human feedback + ~50 system overhead
const isFirstRevision = prev.iteration === 1;
const promptInputTokenEstimate = isFirstRevision
  ? prev.input_token_estimate
  : prev.input_token_estimate
    + draftOutputTokenEstimate
    + Math.ceil(feedback.length / 4)
    + 50;

const reviewEntry = {
  iteration:                    prev.iteration,
  decision,
  feedback,
  draft_snapshot:               draftSnapshot,
  draft_output_token_estimate:  draftOutputTokenEstimate,
  prompt_input_token_estimate:  promptInputTokenEstimate
};

const reviewHistory = [...(prev.review_history || []), reviewEntry];
const maxReached    = !isApproved && prev.iteration >= prev.max_revisions;
const isDone        = isApproved || maxReached;

let terminationReason = 'continue';
if (isApproved)      terminationReason = 'human_approved';
else if (maxReached) terminationReason = 'max_revisions_reached';

return [{ json: {
  input_text:           prev.input_text,
  start_time_ms:        prev.start_time_ms,
  input_token_estimate: prev.input_token_estimate,
  iteration:            prev.iteration + 1,
  max_revisions:        prev.max_revisions,
  current_draft:        prev.current_draft,
  human_feedback:       feedback,
  review_history:       reviewHistory,
  is_approved:          isApproved,
  current_iteration:    prev.iteration,
  human_decision:       decision,
  max_reached:          maxReached,
  is_done:              isDone,
  termination_reason:   terminationReason
} }];

const data   = $input.first().json;
const endMs  = Date.now();
const latMs  = endMs - data.start_time_ms;
const latSec = parseFloat((latMs / 1000).toFixed(2));

const history = data.review_history || [];

// ── Per-revision accurate token accounting ────────────────────────────────────
// Input  : prompt_input_token_estimate stored per revision in Parse Human Decision
//          (revision 1 = initial prompt words × 1.33;
//           revision 2+ = initial + prev_draft + feedback + 50 overhead)
// Output : draft_output_token_estimate = draft chars / 4
// NOTE: lmChatOllama does not expose native Ollama token counts.
// These are character-based estimates. See metadata.limitations.
const totalInputTokens  = history.reduce((s, r) => s + (r.prompt_input_token_estimate || 0), 0);
const totalOutputTokens = history.reduce((s, r) => s + (r.draft_output_token_estimate  || 0), 0);
const totalTokens       = totalInputTokens + totalOutputTokens;

// ── Per-revision execution_trace entries ─────────────────────────────────────
const revisionTrace = {};
history.forEach((entry, idx) => {
  const inTok  = entry.prompt_input_token_estimate || 0;
  const outTok = entry.draft_output_token_estimate  || 0;
  revisionTrace[`revision_${idx + 1}`] = {
    step: idx + 1,
    llm_call: {
      raw_output:    entry.draft_snapshot || '(not captured)',
      input_tokens:  inTok,
      output_tokens: outTok,
      total_tokens:  inTok + outTok,
      latency_ms:    'n/a'   // n8n code nodes do not expose per-node timing
    },
    human_decision: entry.decision,
    human_feedback: entry.feedback || '',
    is_approved:    entry.decision === 'approve'
  };
});

// ── Standard output ───────────────────────────────────────────────────────────
return [{ json: {

  user_prompt:  data.input_text,
  final_answer: data.current_draft,

  metadata: {
    pattern:           'Human in the Loop',
    pattern_category:  'Augmentation and Oversight Pattern',
    run_timestamp:     new Date().toISOString(),
    model:             'qwen2.5:14b',
    model_provider:    'Ollama (local)',
    latency_ms:        latMs,
    latency_seconds:   latSec,
    llm_calls_actual:  history.length,
    llm_calls_max:     data.max_revisions,
    token_usage: {
      total_input_tokens:  totalInputTokens,
      total_output_tokens: totalOutputTokens,
      total_tokens:        totalTokens
    },
    status:             'completed',
    termination_reason: data.termination_reason,

    // Moved from execution_trace — limitations are metadata, not execution data
    limitations: [
      "Token counts are character-based estimates (output: chars/4; input: words×1.33 + context growth). " +
        "lmChatOllama does not expose native Ollama token counts.",
      "per-revision latency_ms is 'n/a' — n8n code nodes do not expose individual node timing; " +
        "only total wall-clock latency_ms is available.",
      "The system prompt uses a generic helpful-assistant persona with no format constraints or " +
        "domain restriction — response style may vary between revisions."
    ],

    // Moved from execution_trace — static schema documentation, not runtime data
    structural_properties: {
      pattern_category:     'Augmentation and Oversight Pattern',
      orchestration_type:   'Human-in-the-loop oversight with AI revision cycle',
      checkpoint_mechanism: 'n8n Wait node (webhook resume)',
      resume_endpoint:      '/webhook-waiting/{executionId}?signature={token}',
      state_passing:        '$json item data piped through nodes; recovered via $() after Wait',
      termination_conditions: [
        "human decision == 'approve'  →  human_approved",
        "iteration >= max_revisions   →  max_revisions_reached (forced close)"
      ],
      agent_count:   1,
      max_revisions: data.max_revisions
    }
  },

  // execution_trace: runtime data only — no static docs, no duplicated drafts
  execution_trace: {
    ...revisionTrace,

    hitl_summary: {
      revision_cycles:         history.length,
      approval_iteration:      data.current_iteration,
      max_revisions:           data.max_revisions,
      human_approved:          data.is_approved,
      max_revisions_triggered: data.max_reached,
      exited_early:            data.current_iteration < data.max_revisions,

      // Lean audit log — no draft_snapshot (already in revision_N.llm_call.raw_output)
      review_log: history.map(r => ({
        iteration: r.iteration,
        decision:  r.decision,
        feedback:  r.feedback || ''
      }))
    }
  }

} }];
